def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    base = []
    for c in range(w):
        counts = Counter(grid[r][c] for r in range(h) if grid[r][c] != 0)
        base.append(counts.most_common(1)[0][0])

    order = []
    for value in base:
        if value not in order:
            order.append(value)
    predecessor = {
        value: order[(i - 1) % len(order)]
        for i, value in enumerate(order)
    }

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                out[r][c] = predecessor[base[c]] if r == c else base[c]
    return out
