def transform(grid):
    h, w = len(grid), len(grid[0])
    top = grid[0]

    # Find the shortest repeating cycle consistent with the visible top row.
    period = w
    for p in range(1, w + 1):
        if all(top[i] == 0 or top[i % p] == 0 or top[i] == top[i % p]
               for i in range(w)):
            period = p
            break

    cycle = [None] * period
    for i, value in enumerate(top):
        if value:
            cycle[i % period] = value

    # Fill any cycle entries not visible in the top row from the surviving
    # grid pattern: for r > c, the cell contains the next cycle value.
    for k in range(period):
        if cycle[k] is None:
            for r in range(h):
                c = k
                if c < w and grid[r][c] != 0:
                    cycle[k] = grid[r][c] if c >= r else None
                    if cycle[k] is not None:
                        break
            if cycle[k] is None:
                for r in range(h):
                    c = (k - 1) % period
                    if c < w and r > c and grid[r][c] != 0:
                        cycle[k] = grid[r][c]
                        break

    out = []
    for r in range(h):
        row = []
        for c in range(w):
            idx = c + 1 if c < r else c
            row.append(cycle[idx % period])
        out.append(row)
    return out
